$ErrorActionPreference='Stop';$root=Join-Path $PSScriptRoot '..\src\WAID.Desktop';$main=Get-Content -Raw (Join-Path $root 'MainWindow.xaml');@('NavDashboard','NavDiagnosis','NavHealth','NavOperations','NavRepairs','NavHistory','NavPlugins')|ForEach-Object{if($main-notmatch$_){throw "Missing automation id $_"}};$app=Get-Content -Raw (Join-Path $root 'App.xaml.cs');if($app-notmatch'StartupRecoveryTitle'){throw 'Missing startup recovery automation id'};Get-ChildItem (Join-Path $root 'Views') -Filter '*.xaml'|ForEach-Object{[xml](Get-Content -Raw $_.FullName)|Out-Null};Write-Host 'Accessibility navigation and recovery smoke checks passed.'
